"use client";

import { useState, type ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./avatar.css";

export type AvatarProps = Omit<ComponentProps<"span">, "children"> & {
  name: string;
  src?: string;
  alt?: string;
  /** Shown as a shape at the corner: filled, half, dash or ring. */
  presence?: "online" | "away" | "busy" | "offline";
};

/** The same name always gets the same orb (six glass orbs; the first follows the accent). */
export function avatarTone(name: string) {
  let hash = 7;
  for (const char of name.trim().toLowerCase()) hash = (hash * 31 + char.codePointAt(0)!) >>> 0;
  return hash % 6;
}

function AvatarContent({ src, initials }: { src?: string; initials: string }) {
  const [failed, setFailed] = useState(false);
  return (
    <>
      <span aria-hidden="true">{initials}</span>
      {src && !failed && (
        <img
          src={src}
          alt=""
          aria-hidden="true"
          width={32}
          height={32}
          decoding="async"
          className="absolute inset-0 size-full object-cover"
          ref={(image) => {
            // A cached or pre-hydration failure may precede the error listener.
            if (image?.complete && image.naturalWidth === 0) setFailed(true);
          }}
          onError={() => setFailed(true)}
        />
      )}
    </>
  );
}

export function Avatar({
  name,
  src,
  alt = name,
  presence,
  className,
  ...props
}: AvatarProps) {
  const words = name.trim().normalize("NFC").split(/\s+/u);
  const initials =
    (Array.from(words[0] ?? "")[0] ?? "?") +
    (words.length > 1 ? (Array.from(words[words.length - 1]!)[0] ?? "") : "");

  return (
    <span
      data-slot="avatar"
      data-tone={avatarTone(name)}
      className={cn(
        "relative inline-flex size-8 shrink-0 items-center justify-center rounded-full text-xs font-semibold",
        className,
      )}
      {...props}
      role={alt ? "img" : undefined}
      aria-label={alt || undefined}
      aria-hidden={!alt || undefined}
    >
      <AvatarContent
        key={src ?? ""}
        src={src}
        initials={initials.toUpperCase()}
      />
      {presence && <span data-slot="avatar-presence" data-presence={presence} aria-hidden="true" />}
    </span>
  );
}

"use client";

import { useEffect, useId, useRef, useState, useSyncExternalStore, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { Avatar } from "./avatar";
import { cn } from "./lib/cn";
import "./shared/hover-card.css";

let closeActive: (() => void) | null = null;

export function HoverCard({
  content,
  children,
  openDelay = 500,
  closeDelay = 140,
  className,
}: {
  content: ReactNode;
  children: ReactNode;
  openDelay?: number;
  closeDelay?: number;
  className?: string;
}) {
  const cardId = useId();
  const trigger = useRef<HTMLSpanElement>(null);
  const [open, setOpen] = useState(false);
  const [box, setBox] = useState({ top: 0, left: 0 });
  const mounted = useSyncExternalStore(() => () => {}, () => true, () => false);
  const dismissed = useRef(false);
  const timer = useRef(0);

  function place() {
    const rect = trigger.current?.getBoundingClientRect();
    if (!rect) return;
    setBox({ top: rect.bottom + 8, left: Math.min(rect.left, window.innerWidth - 312) });
  }

  function show(immediate = false) {
    if (dismissed.current) return;
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => {
      closeActive?.();
      closeActive = () => setOpen(false);
      place();
      setOpen(true);
    }, immediate ? 0 : openDelay);
  }

  function hide() {
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setOpen(false), closeDelay);
  }

  useEffect(() => () => window.clearTimeout(timer.current), []);

  return (
    <span
      ref={trigger}
      className="inline-flex"
      onPointerEnter={() => show(false)}
      onPointerLeave={() => {
        dismissed.current = false;
        hide();
      }}
      onFocusCapture={() => show(true)}
      onBlurCapture={hide}
    >
      <span aria-describedby={open ? cardId : undefined} onKeyDown={(event) => {
        if (event.key === "Enter") show(true);
        if (event.key === "Escape") {
          dismissed.current = true;
          setOpen(false);
        }
      }} onPointerDown={() => {
        if (window.matchMedia("(pointer: coarse)").matches) {
          setOpen((current) => !current);
          if (!open) place();
        }
      }}>
        {children}
      </span>
      {mounted && open ? createPortal(
        <span
          id={cardId}
          role="tooltip"
          data-slot="hover-card"
          className={cn("fixed z-50 w-[18.5rem] max-w-[calc(100vw-1.5rem)] rounded-overlay border p-3 text-sm", className)}
          style={{ top: box.top, left: Math.max(12, box.left) }}
          onPointerEnter={() => window.clearTimeout(timer.current)}
          onPointerLeave={hide}
        >
          {content}
        </span>,
        document.body,
      ) : null}
    </span>
  );
}

export function HoverCardProfile({
  name,
  role,
  bio,
  stats = [],
}: {
  name: string;
  role?: string;
  bio?: string;
  stats?: readonly { label: string; value: string | number }[];
}) {
  return (
    <span className="grid gap-2">
      <span className="flex items-center gap-2">
        <Avatar name={name} alt="" className="size-9" />
        <span>
          <span className="block font-medium">{name}</span>
          {role ? <span className="block text-xs text-muted-foreground">{role}</span> : null}
        </span>
      </span>
      {bio ? <span className="block text-muted-foreground">{bio}</span> : null}
      {stats.length > 0 ? (
        <span className="flex gap-4">
          {stats.map((stat) => (
            <span key={stat.label}>
              <span className="block text-xs text-muted-foreground">{stat.label}</span>
              <span className="font-medium">{stat.value}</span>
            </span>
          ))}
        </span>
      ) : null}
    </span>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* avatar.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Avatars: a light glass orb, two soft hues with a specular highlight and a deeper lower edge. Six tones, assigned per
     person, so a row of people reads as a calm spectrum; dark initials read on every tone at 9:1 or better. */
  [data-slot="avatar"] {
    --av-a: #9ec5ff;
    --av-b: #c4b2ff;
    color: #161616;
    background:
      radial-gradient(circle at 30% 24%, rgb(255 255 255 / 80%), rgb(255 255 255 / 0%) 36%),
      radial-gradient(circle at 76% 84%, color-mix(in oklab, var(--av-b) 78%, #3b2a6b), transparent 58%),
      linear-gradient(140deg, var(--av-a) 12%, var(--av-b) 88%);
    box-shadow: inset 0 0 0 1px rgb(255 255 255 / 34%), inset 0 -4px 8px rgb(0 0 0 / 8%);
  }
  [data-slot="avatar"] > span:first-child {
    position: relative;
    text-shadow: 0 1px 0 rgb(255 255 255 / 35%);
  }
  [data-slot="avatar"] img {
    border-radius: inherit;
  }
  [data-slot="avatar"][data-tone="1"] { --av-a: #a3f0c8; --av-b: #7fd3e6; }
  [data-slot="avatar"][data-tone="2"] { --av-a: #c9adff; --av-b: #ffb2d8; }
  [data-slot="avatar"][data-tone="3"] { --av-a: #ffd6a0; --av-b: #ffab86; }
  [data-slot="avatar"][data-tone="4"] { --av-a: #ffb4a6; --av-b: #ff9ec6; }
  [data-slot="avatar"][data-tone="5"] { --av-a: #b8c6ff; --av-b: #9fe1f0; }
  [data-slot="avatar-presence"] {
    position: absolute;
    right: -3px;
    bottom: -3px;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    box-shadow: 0 0 0 2px var(--background);
  }
  [data-slot="avatar-presence"][data-presence="online"] { background: var(--success); }
  [data-slot="avatar-presence"][data-presence="away"] { background: linear-gradient(90deg, var(--warning) 50%, var(--background) 50%); box-shadow: 0 0 0 2px var(--background), inset 0 0 0 1.5px var(--warning); }
  [data-slot="avatar-presence"][data-presence="busy"] { background: radial-gradient(var(--background) 0 0) center / 5px 1.5px no-repeat, var(--danger); }
  [data-slot="avatar-presence"][data-presence="offline"] { background: var(--background); box-shadow: 0 0 0 2px var(--background), inset 0 0 0 1.5px var(--muted-foreground); }
}

/* Shared by hover-card.tsx, preview-rail.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="hover-card"] {
    transform-origin: top left;
    animation: caliper-menu-enter var(--duration-travel) var(--ease-showcase);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="hover-card"] {
      animation: caliper-menu-enter 400ms var(--ease-showcase);
    }
  }
}

[data-slot="hover-card"] {
  background-color: var(--elevated-glass);
  border-color: color-mix(in srgb, var(--edge-light) 45%, var(--border));
  backdrop-filter: blur(var(--blur-overlay));
  box-shadow:
    var(--shadow-overlay),
    0 0 40px var(--edge-glow),
    inset 0 1px 0 var(--edge-light);
}
